231→// ─── Plan card ────────────────────────────────────────────────────────────────
232→
233→type PlanCardProps = {
234→  plan: (typeof PLANS_DATA)[keyof typeof PLANS_DATA];
235→  isAnnual: boolean;
236→  currentTier: string;
237→  onSubscribe: (planName: string) => void;
238→  onRequestCancel: () => void;
239→  loadingPlan: string | null;
240→};
241→
242→function PlanCard({
243→  plan,
244→  isAnnual,
245→  currentTier,
246→  onSubscribe,
247→  onRequestCancel,
248→  loadingPlan,
249→}: PlanCardProps) {
250→  const isCurrent = currentTier === plan.id;
251→  const isBestValue = "bestValue" in plan && plan.bestValue;
252→  const isCurrentPaid = currentTier !== "free";
253→  const isDowngradeToFree = plan.id === "free" && isCurrentPaid;
254→
255→  const TIER_ORDER: Record<string, number> = {
256→    free: 0,
257→    starter: 1,
258→    pro: 2,
259→    ultimate: 3,
260→  };
261→  const isUpgrade =
262→    !isCurrent &&
263→    plan.id !== "free" &&
264→    (TIER_ORDER[plan.id] ?? 0) > (TIER_ORDER[currentTier] ?? 0);
265→
266→  const shopifyPlan = isAnnual
267→    ? plan.shopifyPlanAnnual
268→    : plan.shopifyPlanMonthly;
269→
270→  const displayPrice = isAnnual ? plan.annualMonthlyPrice : plan.monthlyPrice;
271→
272→  let buttonContent = "Start 7-day free trial";
273→  if (isCurrent) {
274→    buttonContent = "Current plan";
275→  } else if (isDowngradeToFree) {
276→    buttonContent = "Downgrade to Free";
277→  } else if (isUpgrade) {
278→    buttonContent = `Upgrade to ${plan.name}`;
279→  } else if (!isCurrent && plan.id !== "free" && isCurrentPaid) {
280→    buttonContent = `Switch to ${plan.name}`;
281→  }
282→
283→  const handleClick = () => {
284→    if (isCurrent) return;
285→    if (isDowngradeToFree) {
286→      onRequestCancel();
287→    } else if (shopifyPlan) {
288→      onSubscribe(shopifyPlan);
289→    }
290→  };
291→
292→  const isThisLoading = loadingPlan === (shopifyPlan ?? "cancel");
293→
294→  return (
295→    <Card>
296→      <BlockStack gap="400">
297→
298→        {/* Plan name + badges */}
299→        <BlockStack gap="100">
300→          <InlineStack align="space-between" blockAlign="center">
301→            <Text as="h3" variant="headingMd" fontWeight="bold">
302→              {plan.name}
303→            </Text>
304→            <InlineStack gap="150">
305→              {isBestValue && (
306→                <Badge tone="info" icon={StarIcon}>
307→                  Most popular
308→                </Badge>
309→              )}
310→              {isCurrent && <Badge tone="success">Active</Badge>}
311→            </InlineStack>
312→          </InlineStack>
313→          <Text as="p" variant="bodySm" tone="subdued">
314→            {plan.description}
315→          </Text>
316→        </BlockStack>
317→
318→        <Divider />
319→
320→        {/* Price */}
321→        <BlockStack gap="100">
322→          {plan.monthlyPrice === 0 ? (
323→            <>
324→              <Text as="p" variant="headingXl" fontWeight="bold">
325→                Free
326→              </Text>
327→              <Text as="p" variant="bodySm" tone="subdued">
328→                forever
329→              </Text>
330→            </>
331→          ) : (
332→            <>
333→              <InlineStack gap="100" blockAlign="baseline">
334→                <Text as="p" variant="headingXl" fontWeight="bold">
335→                  ${displayPrice}
336→                </Text>
337→                <Text as="p" variant="bodySm" tone="subdued">
338→                  / month
339→                </Text>
340→              </InlineStack>
341→              <Text as="p" variant="bodySm" tone="subdued">
342→                {isAnnual
343→                  ? `billed $${plan.annualPrice} / year`
344→                  : `or $${plan.annualMonthlyPrice}/mo billed annually`}
345→              </Text>
346→            </>
347→          )}
348→        </BlockStack>
349→
350→        {/* CTA button */}
351→        <Button
352→          variant={isCurrent ? "secondary" : "primary"}
353→          tone={isDowngradeToFree ? "critical" : undefined}
354→          onClick={handleClick}
355→          disabled={isCurrent}
356→          loading={isThisLoading}
357→          fullWidth
358→        >
359→          {buttonContent}
360→        </Button>
361→
362→        <Divider />
363→
364→        {/* Features list */}
365→        <BlockStack gap="300">
366→          {plan.features.map((f) => (
367→            <PlanFeature key={f} feature={f} />
368→          ))}
369→        </BlockStack>
370→
371→      </BlockStack>
372→    </Card>
373→  );
374→}
