196→  const { rules, zones, subscription } = useLoaderData<typeof loader>();
197→  const limits = PLAN_LIMITS[subscription.planTier];
198→  const isFreePlan = limits.maxDeliveryRules === 0;
199→  const hasFiniteLimit = limits.maxDeliveryRules < UNLIMITED && !isFreePlan;
200→  const fetcher = useFetcher<typeof action>();
201→  const shopify = useAppBridge();
202→  const navigate = useNavigate();
203→
204→  const [modalOpen, setModalOpen] = useState(false);
205→  const [editingRule, setEditingRule] = useState<Rule | null>(null);
206→
207→  // Form state
208→  const [name, setName] = useState("");
209→  const [zone, setZone] = useState("");
210→  const [zipCodes, setZipCodes] = useState("");
211→  const [minOrderAmount, setMinOrderAmount] = useState("");
212→  const [deliveryFee, setDeliveryFee] = useState("");
213→  const [freeShippingAbove, setFreeShippingAbove] = useState("");
214→  const [estimatedDays, setEstimatedDays] = useState("");
215→  const [cutoffTime, setCutoffTime] = useState("");
216→  const [selectedDays, setSelectedDays] = useState<string[]>([
217→    "Mon",
218→    "Tue",
219→    "Wed",
220→    "Thu",
221→    "Fri",
222→  ]);
223→  const [priority, setPriority] = useState("0");
224→
225→  const actionError =
226→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
227→
228→  const resetForm = useCallback(() => {
229→    setName("");
230→    setZone("");
231→    setZipCodes("");
232→    setMinOrderAmount("");
233→    setDeliveryFee("");
234→    setFreeShippingAbove("");
235→    setEstimatedDays("");
236→    setCutoffTime("");
237→    setSelectedDays(["Mon", "Tue", "Wed", "Thu", "Fri"]);
238→    setPriority("0");
239→    setEditingRule(null);
240→  }, []);
241→
242→  const openCreate = useCallback(() => {
243→    resetForm();
244→    setModalOpen(true);
245→  }, [resetForm]);
246→
247→  const openEdit = useCallback((rule: Rule) => {
248→    setEditingRule(rule);
249→    setName(rule.name);
250→    setZone(rule.zone || "");
251→    setZipCodes(rule.zipCodes || "");
252→    setMinOrderAmount(rule.minOrderAmount != null ? String(rule.minOrderAmount) : "");
253→    setDeliveryFee(rule.deliveryFee != null ? String(rule.deliveryFee) : "");
254→    setFreeShippingAbove(
255→      rule.freeShippingAbove != null ? String(rule.freeShippingAbove) : "",
256→    );
257→    setEstimatedDays(rule.estimatedDays || "");
258→    setCutoffTime(rule.cutoffTime || "");
259→    setSelectedDays(rule.daysOfWeek ? rule.daysOfWeek.split(",") : []);
260→    setPriority(String(rule.priority));
261→    setModalOpen(true);
262→  }, []);
263→
264→  const handleSave = useCallback(() => {
265→    const fd = new FormData();
266→    fd.set("intent", editingRule ? "update" : "create");
267→    if (editingRule) fd.set("id", editingRule.id);
268→    fd.set("name", name);
269→    fd.set("zone", zone);
270→    fd.set("zipCodes", zipCodes);
271→    fd.set("minOrderAmount", minOrderAmount);
272→    fd.set("deliveryFee", deliveryFee);
273→    fd.set("freeShippingAbove", freeShippingAbove);
274→    fd.set("estimatedDays", estimatedDays);
275→    fd.set("cutoffTime", cutoffTime);
276→    fd.set("daysOfWeek", selectedDays.join(","));
277→    fd.set("priority", priority);
278→    fetcher.submit(fd, { method: "POST" });
279→  }, [
280→    editingRule,
281→    name,
282→    zone,
283→    zipCodes,
284→    minOrderAmount,
285→    deliveryFee,
286→    freeShippingAbove,
287→    estimatedDays,
288→    cutoffTime,
289→    selectedDays,
290→    priority,
291→    fetcher,
292→  ]);
293→
294→  const handleDelete = useCallback(
295→    (id: string) => {
296→      const fd = new FormData();
297→      fd.set("intent", "delete");
298→      fd.set("id", id);
299→      fetcher.submit(fd, { method: "POST" });
300→    },
301→    [fetcher],
302→  );
303→
304→  useEffect(() => {
305→    if (fetcher.state === "idle" && fetcher.data) {
306→      if ("success" in fetcher.data && fetcher.data.success) {
307→        const fetcherAction =
308→          "action" in fetcher.data ? fetcher.data.action : "";
309→        if (fetcherAction === "created") {
310→          shopify.toast.show("Rule created");
311→          setModalOpen(false);
312→          resetForm();
313→        } else if (fetcherAction === "updated") {
314→          shopify.toast.show("Rule updated");
315→          setModalOpen(false);
316→          resetForm();
317→        } else if (fetcherAction === "deleted") {
318→          shopify.toast.show("Rule deleted");
319→        } else if (fetcherAction === "toggled") {
320→          shopify.toast.show("Rule status updated");
321→        }
322→      }
323→    }
324→  }, [fetcher.state, fetcher.data, shopify, resetForm]);
325→
326→  const handleToggle = useCallback(
327→    (id: string, isActive: boolean) => {
328→      const fd = new FormData();
329→      fd.set("intent", "toggle");
330→      fd.set("id", id);
331→      fd.set("isActive", String(isActive));
332→      fetcher.submit(fd, { method: "POST" });
333→    },
334→    [fetcher],
335→  );
336→
337→  const toggleDay = useCallback(
338→    (day: string) => {
339→      setSelectedDays((prev) =>
340→        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
341→      );
342→    },
343→    [],
344→  );
345→
346→  const zoneOptions = [
347→    { label: "All zones", value: "" },
348→    ...zones.map((z) => ({ label: z, value: z })),
349→  ];
350→
351→  const tableRows = (rules as Rule[]).map((rule) => [
352→    <InlineStack gap="200" blockAlign="center" key={`name-${rule.id}`}>
353→      <Text as="span" fontWeight="bold">
354→        {rule.name}
355→      </Text>
356→      <Badge tone={rule.isActive ? "success" : undefined}>
357→        {rule.isActive ? "Active" : "Inactive"}
358→      </Badge>
359→    </InlineStack>,
360→    rule.zone || "All",
361→    rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free",
362→    rule.minOrderAmount != null ? `$${rule.minOrderAmount.toFixed(2)}` : "—",
363→    rule.estimatedDays || "—",
364→    rule.daysOfWeek || "All days",
365→    <InlineStack gap="200" key={`actions-${rule.id}`}>
366→      <Tooltip content={rule.isActive ? "Click to deactivate" : "Click to activate"}>
367→        <Button
368→          variant="plain"
369→          tone={rule.isActive ? "success" : undefined}
370→          onClick={() => handleToggle(rule.id, rule.isActive)}
371→          accessibilityLabel={rule.isActive ? "Deactivate rule" : "Activate rule"}
372→        >
373→          {rule.isActive ? "Active" : "Inactive"}
374→        </Button>
375→      </Tooltip>
376→      <Tooltip content="Edit rule">
377→        <Button
378→          size="slim"
379→          variant="tertiary"
380→          onClick={() => openEdit(rule)}
381→          icon={EditIcon}
382→          accessibilityLabel="Edit"
383→        />
384→      </Tooltip>
385→      <Tooltip content="Delete rule">
386→        <Button
387→          size="slim"
388→          variant="tertiary"
389→          tone="critical"
390→          onClick={() => handleDelete(rule.id)}
391→          icon={DeleteIcon}
392→          accessibilityLabel="Delete"
393→        />
394→      </Tooltip>
395→    </InlineStack>,
396→  ]);
397→
398→  return (
399→    <Page
400→      title="Delivery Rules"
401→      subtitle="Configure delivery fees, minimums, schedules, and conditions per zone"
402→      backAction={{ onAction: () => navigate("/app") }}
403→      primaryAction={
404→        isFreePlan
405→          ? undefined
406→          : {
407→              content: "Add Rule",
408→              icon: PlusIcon,
409→              onAction: openCreate,
410→            }
411→      }
412→    >
413→      <Box paddingBlockEnd="1600">
414→      <Layout>
415→        {isFreePlan && (
416→          <Layout.Section>
417→            <Banner
418→              tone="info"
419→              title="Delivery rules require a paid plan"
420→              action={{
421→                content: "View pricing plans",
422→                url: "/app/pricing",
423→              }}
424→            >
425→              <Text as="p">
426→                Upgrade to the Starter plan or higher to create delivery rules
427→                with custom fees, schedules, and zone conditions.
428→              </Text>
429→            </Banner>
430→          </Layout.Section>
431→        )}
432→        {hasFiniteLimit && (
433→          <Layout.Section>
434→            <InlineStack align="end">
435→              <Badge
436→                tone={
437→                  (rules as Rule[]).length >= limits.maxDeliveryRules
438→                    ? "warning"
439→                    : undefined
440→                }
441→              >
442→                {`${(rules as Rule[]).length}/${limits.maxDeliveryRules} rules used`}
443→              </Badge>
444→            </InlineStack>
445→          </Layout.Section>
446→        )}
447→        <Layout.Section>
448→          <Card padding="0">
449→            {(rules as Rule[]).length === 0 ? (
450→              <EmptyState
451→                heading="No delivery rules yet"
452→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
453→                action={
454→                  isFreePlan
455→                    ? {
456→                        content: "Upgrade to create rules",
457→                        url: "/app/pricing",
458→                      }
459→                    : {
460→                        content: "Create your first rule",
461→                        onAction: openCreate,
462→                      }
463→                }
464→              >
465→                <Text as="p">
466→                  Delivery rules let you set fees, minimum order amounts,
467→                  estimated delivery times, and delivery schedules for different
468→                  zones. Rules are evaluated by priority order.
469→                </Text>
470→              </EmptyState>
471→            ) : (
472→              <DataTable
473→                columnContentTypes={[
474→                  "text",
475→                  "text",
476→                  "text",
477→                  "text",
478→                  "text",
479→                  "text",
480→                  "text",
481→                ]}
482→                headings={[
483→                  "Rule Name",
484→                  "Zone",
485→                  "Delivery Fee",
486→                  "Min. Order",
487→                  "ETA",
488→                  "Days",
489→                  "Actions",
490→                ]}
491→                rows={tableRows}
492→                hoverable
493→              />
494→            )}
495→          </Card>
496→        </Layout.Section>
497→      </Layout>
498→      </Box>
499→
500→      {/* Create / Edit Modal */}
501→      <Modal
502→        open={modalOpen}
503→        onClose={() => {
504→          setModalOpen(false);
505→          resetForm();
506→        }}
507→        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
508→        primaryAction={{
509→          content: editingRule ? "Save Changes" : "Create Rule",
510→          onAction: handleSave,
511→        }}
512→        secondaryActions={[
513→          {
514→            content: "Cancel",
515→            onAction: () => {
516→              setModalOpen(false);
517→              resetForm();
518→            },
519→          },
520→        ]}
521→      >
522→        <Modal.Section>
523→          <BlockStack gap="400">
524→            {actionError && <Banner tone="critical">{actionError}</Banner>}
525→
526→            <TextField
527→              label="Rule Name"
528→              value={name}
529→              onChange={setName}
530→              placeholder="e.g. Manhattan Standard Delivery"
531→              autoComplete="off"
532→              helpText="A descriptive name for this delivery rule."
533→            />
534→
535→            <InlineGrid columns={2} gap="300">
536→              <Select
537→                label="Zone"
538→                options={zoneOptions}
539→                value={zone}
540→                onChange={setZone}
541→                helpText="Apply this rule to a specific zone, or all zones."
542→              />
543→              <TextField
544→                label="Priority"
545→                type="number"
546→                value={priority}
547→                onChange={setPriority}
548→                autoComplete="off"
549→                helpText="Lower number = higher priority."
550→              />
551→            </InlineGrid>
552→
553→            <TextField
554→              label="Specific Zip Codes (optional)"
555→              value={zipCodes}
556→              onChange={setZipCodes}
557→              placeholder="10001, 10002, 10003"
558→              autoComplete="off"
559→              helpText="Comma-separated zip codes. Leave empty to apply to all zip codes in the zone."
560→            />
561→
562→            <Divider />
563→            <Text as="h3" variant="headingSm">
564→              Pricing
565→            </Text>
566→
567→            <InlineGrid columns={2} gap="300">
568→              <TextField
569→                label="Delivery Fee ($)"
570→                type="number"
571→                value={deliveryFee}
572→                onChange={setDeliveryFee}
573→                placeholder="0.00"
574→                autoComplete="off"
575→                helpText="Leave empty for free delivery."
576→              />
577→              <TextField
578→                label="Min. Order Amount ($)"
579→                type="number"
580→                value={minOrderAmount}
581→                onChange={setMinOrderAmount}
582→                placeholder="0.00"
583→                autoComplete="off"
584→                helpText="Minimum order to qualify for delivery."
585→              />
586→            </InlineGrid>
587→
588→            <TextField
589→              label="Free Shipping Above ($)"
590→              type="number"
591→              value={freeShippingAbove}
592→              onChange={setFreeShippingAbove}
593→              placeholder="e.g. 50.00"
594→              autoComplete="off"
595→              helpText="Waive the delivery fee for orders above this amount."
596→            />
597→
598→            <Divider />
599→            <Text as="h3" variant="headingSm">
600→              Schedule
601→            </Text>
602→
603→            <InlineGrid columns={2} gap="300">
604→              <TextField
605→                label="Estimated Delivery"
606→                value={estimatedDays}
607→                onChange={setEstimatedDays}
608→                placeholder="e.g. 2-3 days"
609→                autoComplete="off"
610→              />
611→              <TextField
612→                label="Order Cutoff Time"
613→                value={cutoffTime}
614→                onChange={setCutoffTime}
615→                placeholder="e.g. 14:00"
616→                autoComplete="off"
617→                helpText="Orders after this time ship next delivery day."
618→              />
619→            </InlineGrid>
620→
621→            <BlockStack gap="200">
622→              <Text as="p" variant="bodyMd">
623→                Delivery Days
624→              </Text>
625→              <InlineStack gap="300" wrap>
626→                {DAYS_OPTIONS.map((day) => (
627→                  <Checkbox
628→                    key={day.value}
629→                    label={day.label}
630→                    checked={selectedDays.includes(day.value)}
631→                    onChange={() => toggleDay(day.value)}
632→                  />
633→                ))}
634→              </InlineStack>
635→            </BlockStack>
636→          </BlockStack>
637→        </Modal.Section>
638→      </Modal>
639→    </Page>
640→  );
641→}
642→
643→export function ErrorBoundary() {
644→  return boundary.error(useRouteError());
645→}
646→
647→export const headers: HeadersFunction = (headersArgs) => {
648→  return boundary.headers(headersArgs);
649→};
